<script setup>
import Icon from './Icon.vue'
import {formatPrice} from '../lib/domain'
defineProps({property:Object,favorite:Boolean,manage:Boolean})
defineEmits(['open','favorite','edit'])
</script>
<template><article class="property-card"><div class="property-photo"><img v-if="property.image" :src="property.image" :alt="property.type + ' en ' + property.commune" loading="lazy" @error="$event.target.style.display='none'"><span class="photo-label">{{property.operation}}</span><button v-if="!manage" class="favorite" :class="{selected:favorite}" :aria-label="favorite ? 'Quitar de favoritos' : 'Guardar en favoritos'" :aria-pressed="favorite" @click="$emit('favorite',property.id)"><Icon name="heart"/></button><span v-else class="photo-status">{{property.status}}</span></div><div class="property-body"><div class="property-location"><Icon name="pin"/>{{property.commune}} · {{property.sector || property.type}}</div><button class="card-title" @click="$emit('open',property)">{{property.title}}</button><div class="property-specs">{{property.beds}} dorm. <span>·</span> {{property.baths}} baños <span>·</span> {{property.area}} m²</div><div class="property-bottom"><strong>{{formatPrice(property)}}</strong><button class="text-button" @click="manage ? $emit('edit',property) : $emit('open',property)">{{manage ? 'Administrar' : 'Ver propiedad'}}<Icon name="arrow"/></button></div></div></article></template>
